//! Geometry against vectors drawn from Ruby 3.3 itself
//! (tests/fixtures/geometry_vectors.json, generated by
//! gen_geometry_fixtures.rb at the repository root): the pressed wedges, the
//! reading paths, the glyph strokes and the plate dimensions must match the
//! original byte for byte.

use rustergraphia::grille::{Grille, Part};
use rustergraphia::layout::{self, Layout};
use rustergraphia::ruby_random::RubyRandom;
use rustergraphia::{glyphs, stylus, Line};
use serde_json::Value;

fn vectors() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/geometry_vectors.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn line_of(key: &str) -> Line {
    let parts: Vec<i32> = key.split(',').map(|n| n.parse().unwrap()).collect();
    [parts[0], parts[1], parts[2], parts[3]]
}

#[test]
fn every_stroke_presses_as_ruby_presses_it() {
    let v = vectors();
    for (key, want) in v["press"].as_object().unwrap() {
        let got = stylus::press(line_of(key));
        assert_eq!(&got, want.as_str().unwrap(), "stroke {key}");
    }
}

#[test]
fn seeded_wedges_match() {
    let v = vectors();
    let cases: [(Line, i64); 4] = [
        ([100, 0, 50, 0], 1),
        ([50, 0, 50, 150], 7),
        ([50, 50, 100, 0], 42),
        ([0, 150, 100, 150], -3),
    ];
    for ((stroke, seed), want) in cases.iter().zip(v["wedges"].as_array().unwrap()) {
        let polygons = stylus::wedge(*stroke, &mut RubyRandom::new(*seed));
        let got: Vec<String> = polygons
            .iter()
            .map(|poly| stylus::outline(poly, 0.0, 0.0))
            .collect();
        let want: Vec<String> = want
            .as_array()
            .unwrap()
            .iter()
            .map(|s| s.as_str().unwrap().to_string())
            .collect();
        assert_eq!(got, want, "stroke {stroke:?} seed {seed}");
    }
}

#[test]
fn every_path_is_rubys_at_every_side() {
    let v = vectors();
    for layout in layout::KEYLESS {
        let by_size = v["paths"][layout.name()].as_array().unwrap();
        for (i, want) in by_size.iter().enumerate() {
            let got: Vec<Vec<Value>> = layout::path(i + 1, &layout)
                .unwrap()
                .into_iter()
                .map(|(row, col, turned)| {
                    vec![Value::from(row), Value::from(col), Value::from(turned)]
                })
                .collect();
            let want: Vec<Vec<Value>> = want
                .as_array()
                .unwrap()
                .iter()
                .map(|step| step.as_array().unwrap().clone())
                .collect();
            assert_eq!(got, want, "{} at {}", layout.name(), i + 1);
        }
    }
}

#[test]
fn glyph_strokes_match() {
    let v = vectors();
    for (num, want) in v["strokes"].as_object().unwrap() {
        let got: Vec<Vec<i32>> = glyphs::strokes(num.parse().unwrap(), 7, 11)
            .into_iter()
            .map(|line| line.to_vec())
            .collect();
        let want: Vec<Vec<i32>> = want
            .as_array()
            .unwrap()
            .iter()
            .map(|line| {
                line.as_array()
                    .unwrap()
                    .iter()
                    .map(|n| n.as_i64().unwrap() as i32)
                    .collect()
            })
            .collect();
        assert_eq!(got, want, "strokes of {num}");
    }
}

#[test]
fn dimensions_and_cells_match() {
    let v = vectors();
    let cases = [(4usize, false), (4, true), (9, false), (16, true)];
    for ((len, tally), want) in cases.iter().zip(v["dims"].as_array().unwrap()) {
        let (w, h, cols, rows) = layout::dimensions(*len, &Layout::Phaistos, *tally).unwrap();
        let got = [w as i64, h as i64, cols as i64, rows as i64];
        let want: Vec<i64> = want
            .as_array()
            .unwrap()
            .iter()
            .map(|n| n.as_i64().unwrap())
            .collect();
        assert_eq!(got.to_vec(), want, "dimensions of {len} (tally {tally})");
    }

    let grille = Layout::Grille(Grille::new("K7Q2M-ZXB4P", Part::Whole).unwrap());
    let (w, h, cols, rows) = layout::dimensions(16, &grille, false).unwrap();
    let want: Vec<i64> = v["grille_dims"]
        .as_array()
        .unwrap()
        .iter()
        .map(|n| n.as_i64().unwrap())
        .collect();
    assert_eq!(vec![w as i64, h as i64, cols as i64, rows as i64], want);

    let (x, y) = layout::origin(1, 2, &grille);
    let want: Vec<i64> = v["grille_origin"]
        .as_array()
        .unwrap()
        .iter()
        .map(|n| n.as_i64().unwrap())
        .collect();
    assert_eq!(vec![x as i64, y as i64], want);

    let lines = [[50, 50, 150, 50], [10, 10, 20, 20], [290, 250, 290, 210]];
    for (line, want) in lines.iter().zip(v["cell_of"].as_array().unwrap()) {
        let (row, col) = layout::cell_of(*line, &Layout::Phaistos);
        let want: Vec<i64> = want
            .as_array()
            .unwrap()
            .iter()
            .map(|n| n.as_i64().unwrap())
            .collect();
        assert_eq!(vec![row as i64, col as i64], want, "cell of {line:?}");
    }
}

/// Ruby's `Float#round(1)` as interpolated, on 2,031 values Ruby rounded
/// itself (tests/fixtures/ruby_round1.json): every magnitude and sign,
/// halves, and the underflow shortcut that gives -0.0036 a positive zero.
#[test]
fn rounding_to_a_tenth_is_rubys() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/ruby_round1.json"
    );
    let cases: Vec<(f64, String)> =
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let wrong: Vec<_> = cases
        .iter()
        .filter(|(value, want)| rustergraphia::stylus::round1_as_ruby(*value) != *want)
        .collect();
    assert!(
        wrong.is_empty(),
        "{} of {} differ: {:?}",
        wrong.len(),
        cases.len(),
        &wrong[..wrong.len().min(5)]
    );
}
